insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$uruka$t$, $t$Uruka$t$, $t$উৰুকা$t$, $t$The night before Magh (Bhogali) Bihu, spent feasting and staying awake around a bonfire.$t$, $t$মাঘ (ভোগালী) বিহুৰ আগৰ নিশা, যিটো ভোজ-ভাত খাই আৰু মেজিৰ কাষত সাৰে থাকি পাৰ কৰা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$meji$t$, $t$Meji$t$, $t$মেজি$t$, $t$The bonfire built for Magh Bihu and burnt early on the morning of the festival.$t$, $t$মাঘ বিহুৰ বাবে সজা জুইৰ ঘৰ, যিটো বিহুৰ দিনা ৰাতিপুৱা জ্বলোৱা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$bhelaghar$t$, $t$Bhelaghar$t$, $t$ভেলাঘৰ$t$, $t$A temporary hut of straw and bamboo built by young people for the Uruka night feast.$t$, $t$উৰুকাৰ ভোজৰ বাবে ডেকা-গাভৰুৱে খেৰ আৰু বাঁহেৰে সজা অস্থায়ী ঘৰ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$husori$t$, $t$Husori$t$, $t$হুচৰি$t$, $t$Groups who go from house to house during Bohag Bihu singing songs and blessing each family.$t$, $t$বহাগ বিহুৰ সময়ত ঘৰে ঘৰে গৈ গীত গাই প্ৰতিটো পৰিয়ালক আশীৰ্বাদ দিয়া দল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$bihuwan$t$, $t$Bihuwan$t$, $t$বিহুৱান$t$, $t$A gift, usually a gamosa, given to elders and loved ones at Bohag Bihu.$t$, $t$বহাগ বিহুত ডাঙৰ আৰু মৰমৰ মানুহক দিয়া উপহাৰ, সাধাৰণতে এখন গামোচা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$sattra$t$, $t$Sattra$t$, $t$সত্ৰ$t$, $t$A monastery-like centre of Sankardev's Neo-Vaishnavite faith, for prayer, music, dance and learning.$t$, $t$শংকৰদেৱৰ নৱ-বৈষ্ণৱ ধৰ্মৰ উপাসনা, গীত-মাত, নৃত্য আৰু শিক্ষাৰ মঠসদৃশ কেন্দ্ৰ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$namghar$t$, $t$Namghar$t$, $t$নামঘৰ$t$, $t$A prayer hall where people gather to sing and pray. Every Sattra has one, and most Assamese villages too.$t$, $t$মানুহ গোট খাই নাম-প্ৰসংগ কৰা উপাসনা গৃহ। প্ৰতিখন সত্ৰত আৰু বেছিভাগ অসমীয়া গাঁৱতো নামঘৰ থাকে।$t$) on conflict (slug) do nothing;
