insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$ankiya-naat$t$, $t$Ankiya Naat$t$, $t$অংকীয়া নাট$t$, $t$One-act plays created by Sankardev. Their stage performance is called Bhaona.$t$, $t$শংকৰদেৱে সৃষ্টি কৰা এক অংকৰ নাট। ইয়াৰ মঞ্চ পৰিৱেশনক ভাওনা বোলা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$borgeet$t$, $t$Borgeet$t$, $t$বৰগীত$t$, $t$Devotional songs composed by Sankardev and Madhavdev.$t$, $t$শংকৰদেৱ আৰু মাধৱদেৱে ৰচনা কৰা ভক্তিমূলক গীত।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$classical-dance$t$, $t$Classical dance$t$, $t$শাস্ত্ৰীয় নৃত্য$t$, $t$A dance form recognised by the Sangeet Natak Akademi for its old, rule-based tradition. Sattriya is one of them.$t$, $t$প্ৰাচীন আৰু নিয়মবদ্ধ পৰম্পৰাৰ বাবে সংগীত নাটক অকাডেমীয়ে স্বীকৃতি দিয়া নৃত্য। সত্ৰীয়া তাৰে এটা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$geographical-indication$t$, $t$Geographical Indication (GI) tag$t$, $t$ভৌগোলিক সূচক (জি আই) চিহ্ন$t$, $t$An official label showing that a product comes from a particular place and has qualities linked to it.$t$, $t$কোনো সামগ্ৰী এটা নিৰ্দিষ্ট ঠাইৰ আৰু তাৰ গুণ সেই ঠাইৰ সৈতে জড়িত বুলি দেখুওৱা চৰকাৰী স্বীকৃতি।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$charyapada$t$, $t$Charyapada$t$, $t$চৰ্যাপদ$t$, $t$Buddhist songs of about the 8th to 10th century, taken as the earliest examples of Assamese literature.$t$, $t$প্ৰায় অষ্টমৰ পৰা দশম শতিকাৰ বৌদ্ধ গীত, যাক অসমীয়া সাহিত্যৰ আটাইতকৈ পুৰণি নিদৰ্শন বুলি ধৰা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$buranji$t$, $t$Buranji$t$, $t$বুৰঞ্জী$t$, $t$Prose chronicles of the Ahom court that recorded events and history.$t$, $t$ঘটনা আৰু ইতিহাস লিপিবদ্ধ কৰা আহোম ৰাজসভাৰ গদ্য ইতিহাস গ্ৰন্থ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$jonaki-era$t$, $t$Jonaki era$t$, $t$জোনাকী যুগ$t$, $t$The start of modern Assamese literature, named after the magazine Jonaki (1889).$t$, $t$আধুনিক অসমীয়া সাহিত্যৰ আৰম্ভণি, জোনাকী (১৮৮৯) আলোচনীৰ নামেৰে নামকৰণ কৰা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$jnanpith-award$t$, $t$Jnanpith Award$t$, $t$জ্ঞানপীঠ বঁটা$t$, $t$India's highest literary award, given every year to a writer in an Indian language.$t$, $t$ভাৰতীয় ভাষাৰ এগৰাকী সাহিত্যিকক প্ৰতি বছৰে দিয়া দেশৰ সৰ্বোচ্চ সাহিত্য বঁটা।$t$) on conflict (slug) do nothing;
