insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Bihu$t$, $t$The three Bihus of Assam and the customs of each.$t$, 'draft', $t$Bihu, Wikipedia: https://en.wikipedia.org/wiki/Bihu$t$, date '2026-11-24' from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Bihu is the main festival of Assam and its state festival. There are three Bihus in the year, linked to the farming cycle.$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 2, 'list', 'heritage', $t$Rongali or Bohag Bihu (April): the spring festival and the Assamese New Year. It is the most important Bihu.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Bohag Bihu$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$The first day, Goru Bihu (usually 14 April), is for cattle: they are washed and smeared with turmeric. The next day, Manuh Bihu, is New Year's Day, when people give a {{term:bihuwan}} to elders. {{term:husori|Husori}} groups then go singing from house to house.$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h2', 5, 'heading', 'normal', $t$Magh Bihu$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 6, 'paragraph', 'normal', $t$On {{term:uruka}} night, young people build a {{term:bhelaghar}} and a {{term:meji}}, and feast together. The Meji is burnt the next morning.$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$The Bihu dance is the state dance. It is played with the dhol, the pepa (buffalo-horn pipe) and the taal (cymbals).$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Rongali = Bohag (April), Kongali = Kati (Oct/Nov), Bhogali = Magh (January).$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$বিহু$t$, $t$অসমৰ তিনিটা বিহু আৰু প্ৰতিটোৰ ৰীতি-নীতি।$t$, 'draft', $t$Bihu, Wikipedia: https://en.wikipedia.org/wiki/Bihu$t$, date '2026-11-24' from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$বিহু অসমৰ প্ৰধান উৎসৱ আৰু ৰাজ্যিক উৎসৱ। বছৰত তিনিটা বিহু হয়, যিবোৰ কৃষিচক্ৰৰ সৈতে জড়িত।$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'l1', 2, 'list', 'heritage', $t$ৰঙালী বা বহাগ বিহু (এপ্ৰিল): বসন্তৰ উৎসৱ আৰু অসমীয়া নৱবৰ্ষ। ই আটাইতকৈ গুৰুত্বপূৰ্ণ বিহু।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'h1', 3, 'heading', 'normal', $t$বহাগ বিহু$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$প্ৰথম দিনটো গৰু বিহু (সাধাৰণতে ১৪ এপ্ৰিল): গৰুক গা ধুৱাই হালধি-মাহ লগোৱা হয়। পিছদিনা মানুহ বিহু, নৱবৰ্ষৰ দিন, যেতিয়া ডাঙৰসকলক {{term:bihuwan|বিহুৱান}} দিয়া হয়। তাৰ পিছত {{term:husori|হুচৰিৰ}} দলে ঘৰে ঘৰে গীত গাই ফুৰে।$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'h2', 5, 'heading', 'normal', $t$মাঘ বিহু$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 6, 'paragraph', 'normal', $t${{term:uruka|উৰুকাৰ}} নিশা ডেকা-গাভৰুৱে {{term:bhelaghar|ভেলাঘৰ}} আৰু {{term:meji|মেজি}} সাজি একেলগে ভোজ খায়। পিছদিনা ৰাতিপুৱা মেজি জ্বলোৱা হয়।$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$বিহু নাচ ৰাজ্যিক নৃত্য। ইয়াত ঢোল, পেঁপা (ম'হৰ শিঙৰ বাদ্য) আৰু তাল বজোৱা হয়।$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ৰঙালী = বহাগ (এপ্ৰিল), কঙালী = কাতি (অক্টো/নৱে), ভোগালী = মাঘ (জানুৱাৰী)।$t$, null from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$sattriya-and-sattra$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$culture$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Sattriya dance and the Sattra institution$t$, $t$The Sattras founded in Sankardev's tradition, and the classical dance that grew in them.$t$, 'draft', $t$Satra, Wikipedia: https://en.wikipedia.org/wiki/Sattra
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$A {{term:sattra}} is a centre of the {{term:neo-vaishnavism|Neo-Vaishnavite}} faith started by Srimanta Sankardev. Sankardev is said to have set up his first Sattra at Bordowa, his birthplace.$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$Every Sattra has a {{term:namghar}} (also called kirtanghar), its prayer hall. Each Sattra is headed by a {{term:satradhikar}}. The Asam Satra Mahasabha counts 862 Sattras in Assam and West Bengal.$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 3, 'paragraph', 'heritage', $t$Majuli became the main centre of the Sattra tradition. Well-known Sattras include Auniati, Dakhinpat, Garamur and Kamalabari in Majuli, and the Barpeta Sattra, built by Madhavdev.$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h1', 4, 'heading', 'normal', $t$Sattriya dance$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$Sattriya dance was created by Sankardev as part of Bhaona, the stage performance of his {{term:ankiya-naat|Ankiya Naat}}. It was kept alive in the Sattras for centuries.$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p5', 6, 'paragraph', 'event', $t$On 15 November 2000, the Sangeet Natak Akademi recognised Sattriya as one of the eight {{term:classical-dance|classical dances}} of India.$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: first Sattra at Bordowa; Sattriya recognised as a classical dance on 15 November 2000.$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$সত্ৰীয়া নৃত্য আৰু সত্ৰ অনুষ্ঠান$t$, $t$শংকৰদেৱৰ পৰম্পৰাত প্ৰতিষ্ঠিত সত্ৰ, আৰু তাত গঢ় লোৱা শাস্ত্ৰীয় নৃত্য।$t$, 'draft', $t$Satra, Wikipedia: https://en.wikipedia.org/wiki/Sattra
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:sattra|সত্ৰ}} শ্ৰীমন্ত শংকৰদেৱে প্ৰৱৰ্তন কৰা {{term:neo-vaishnavism|নৱ-বৈষ্ণৱ}} ধৰ্মৰ কেন্দ্ৰ। কোৱা হয় যে শংকৰদেৱে তেওঁৰ জন্মস্থান বৰদোৱাত প্ৰথম সত্ৰ স্থাপন কৰিছিল।$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$প্ৰতিখন সত্ৰত এটা {{term:namghar|নামঘৰ}} (কীৰ্তনঘৰ বুলিও কোৱা হয়) থাকে। প্ৰতিখন সত্ৰৰ মুৰব্বী এগৰাকী {{term:satradhikar|সত্ৰাধিকাৰ}}। অসম সত্ৰ মহাসভাৰ হিচাপমতে অসম আৰু পশ্চিমবংগত ৮৬২ খন সত্ৰ আছে।$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 3, 'paragraph', 'heritage', $t$মাজুলী সত্ৰ পৰম্পৰাৰ মূল কেন্দ্ৰ হৈ পৰে। জনাজাত সত্ৰসমূহৰ ভিতৰত মাজুলীৰ আউনীআটী, দক্ষিণপাট, গড়মূৰ আৰু কমলাবাৰী, আৰু মাধৱদেৱে নিৰ্মাণ কৰা বৰপেটা সত্ৰ উল্লেখযোগ্য।$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'h1', 4, 'heading', 'normal', $t$সত্ৰীয়া নৃত্য$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$শংকৰদেৱে তেওঁৰ {{term:ankiya-naat|অংকীয়া নাটৰ}} মঞ্চ পৰিৱেশন ভাওনাৰ অংশ হিচাপে সত্ৰীয়া নৃত্য সৃষ্টি কৰিছিল। শতিকাজুৰি সত্ৰসমূহে ইয়াক জীয়াই ৰাখে।$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p5', 6, 'paragraph', 'event', $t$২০০০ চনৰ ১৫ নৱেম্বৰত সংগীত নাটক অকাডেমীয়ে সত্ৰীয়াক ভাৰতৰ আঠটা {{term:classical-dance|শাস্ত্ৰীয় নৃত্যৰ}} এটা হিচাপে স্বীকৃতি দিয়ে।$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: প্ৰথম সত্ৰ বৰদোৱাত; ১৫ নৱেম্বৰ ২০০০ত সত্ৰীয়াই শাস্ত্ৰীয় নৃত্যৰ স্বীকৃতি পায়।$t$, null from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
