insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Each community of Assam has its own dances and songs. These are the ones most often asked about:$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
