insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Devotional music$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t${{term:borgeet|Borgeet}} are devotional songs composed by Sankardev and Madhavdev. Madhavdev alone wrote 191 Borgeets.$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$Ojapali has several forms: Byah (Vyas) Ojapali based on the epics, Sukananni (Maroi) Ojapali linked to the goddess Manasa, Ramayani Ojapali and Sattriya Ojapali.$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Bagurumba = butterfly dance of the Bodos; Ojapali = Oja and Pali, home district Darrang.$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$লোকনৃত্য আৰু লোকসংগীত$t$, $t$বাগৰুম্বা, ওজাপালি, বৰগীত আৰু অসমৰ অন্যান্য নৃত্য-গীতৰ পৰম্পৰা।$t$, 'draft', $t$Bagurumba, Wikipedia: https://en.wikipedia.org/wiki/Bagurumba
