insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'h1', 3, 'heading', 'normal', $t$ভক্তিমূলক সংগীত$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t${{term:borgeet|বৰগীত}} শংকৰদেৱ আৰু মাধৱদেৱে ৰচনা কৰা ভক্তিমূলক গীত। মাধৱদেৱে অকলেই ১৯১ টা বৰগীত ৰচনা কৰিছিল।$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$ওজাপালিৰ কেইবাটাও ৰূপ আছে: মহাকাব্যভিত্তিক ব্যাহ (ব্যাস) ওজাপালি, মনসা দেৱীৰ সৈতে জড়িত সুকনান্নি (মাৰৈ) ওজাপালি, ৰামায়ণী ওজাপালি আৰু সত্ৰীয়া ওজাপালি।$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: বাগৰুম্বা = বড়োসকলৰ পখিলা নৃত্য; ওজাপালি = ওজা আৰু পালি, কেন্দ্ৰ দৰং জিলা।$t$, null from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
