insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 3, 'list', 'event', $t$Hema Saraswati (14th century): the earliest known Assamese writer; wrote Prahlad Charita.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$From the 17th century, the Ahom court wrote many {{term:buranji|Buranjis}}, which are important early works of Assamese prose.$t$, null from public.content where slug = $t$assamese-literature$t$ on conflict do nothing;
